import{_ as t,o as r,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-11-04 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-11-04 :: Ceph Orchestration Meeting","date":"2019-11-04T00:00:00.000Z","updated":"2019-11-05T00:00:00.000Z","tags":["Ceph","Rook","Orchestrator","Distributed Storage","Kubernetes"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-04_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-11-04_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),e={name:"posts/2019/2019-11-04_-_-_Ceph_Orchestration_Meeting.md"};function s(n,o,p,a,_,g){return r(),l("div",null,[...o[0]||(o[0]=[i("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Jerry、Rick、DW、Sebastian、Lauren等</p><p><strong>会议主题</strong>： Rook 项目进展讨论及行动计划</p><p><strong>关键细节及议题</strong>：</p><ul><li><strong>Orchestrator 工作流</strong>： <ul><li>Jerry 提到 Orchestrator 工作流需要支持多站点设置，并创建区域。</li><li>Rick 表示 Rook 只支持独立区域，不支持多站点配置。</li><li>Jerry 认为可能需要一个更高级的工作流，先进行多站点操作，然后再启动 Demon，或者创建其他所需资源。</li></ul></li><li><strong>Rook 与 Octopus</strong>： <ul><li>DW 更新了 Rook 的路线图，并确保 Rook 准备好 Octopus 的发布。</li><li>Rick 提到需要查看 Octopus 的待办事项列表，并确定 Rook 需要实现的功能。</li></ul></li><li><strong>Python 客户端库</strong>： <ul><li>Jerry 提到将 Python 客户端库放入 Rook 仓库可以使版本依赖管理更加简洁。</li><li>DW 同意将 Python 客户端库添加到 Rook 仓库中。</li></ul></li><li><strong>驱动器组支持</strong>： <ul><li>Jerry 讨论了将驱动器组集成到 Rook Orchestrator 中的方案。</li><li>他建议在 Orchestrator 层面获取驱动器信息，并将其传递给 Rook。</li><li>他还提到应该在 Rook 安全集群内部实现卷创建，而不是依赖于外部实现。</li></ul></li><li><strong>闪烁灯集成</strong>： <ul><li>Rick 提到闪烁灯集成目前受阻，需要等待相关 pull request 合并。</li><li>Sebastian 提到可以将闪烁灯集成到 Europe Manager 模块中。</li></ul></li><li><strong>远程调用问题</strong>： <ul><li>Lauren 提到远程调用库不支持 SSH 选项参数，需要升级库版本。</li><li>Jerry 计划使用 pip 安装新版本的远程调用库。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>Jerry 将继续与 Ollie 讨论 RGB 工作内容。</li><li>DW 将更新 Rook 的路线图，确保 Rook 准备好 Octopus 的发布。</li><li>将 Python 客户端库添加到 Rook 仓库中。</li><li>探索将驱动器组集成到 Rook Orchestrator 中的方案。</li><li>解决远程调用库的问题。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Jerry 与 Ollie 讨论 RGB 工作内容。</li><li>DW 更新 Rook 路线图。</li><li>完成将 Python 客户端库添加到 Rook 仓库的工作。</li><li>探索将驱动器组集成到 Rook Orchestrator 中的方案。</li><li>解决远程调用库的问题。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph 领域的英文关键词，如：Orchestrator、Rook、Octopus、RBD、Python、SSH、RemoteOH、DRBD、Orchestrator、Rook、Octopus、RBD、Rook、Python、SSH、RemoteOH 等。</li><li>会议中讨论了一些技术细节，如：工作流、版本依赖管理、驱动器组、闪烁灯、远程调用等。</li></ul>",13)])])}const R=t(e,[["render",s]]);export{u as __pageData,R as default};
